from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class DistNamesSlot(SchemaObject):
    config = SchemaField(name="config")
    runtime = SchemaField(name="runtime")

    def __init__(self, config, runtime):
        super(DistNamesSlot, self).__init__()
        self.config = config
        self.runtime = runtime


class NGLinksResponseASMV1(SchemaObject):
    served_amf_id = SchemaField(name="servedAmfId", not_null=True)
    amf_name = SchemaField(name="amfName", optional=True)
    amf_ip_address = SchemaField(name="amfIPAddress", not_null=True)
    ng_link_status = SchemaField(name="ngLinkStatus")
    administrative_state = SchemaField(name="administrativeState", not_null=True)
    dist_names = SchemaField(name="distNames", klass=DistNamesSlot, not_null=True)

    def __init__(self, served_amf_id, amf_name, amf_ip_address, ng_link_status, administrative_state, dist_names):
        super(NGLinksResponseASMV1, self).__init__()
        self.served_amf_id = served_amf_id
        self.amf_name = amf_name
        self.amf_ip_address = amf_ip_address
        self.ng_link_status = ng_link_status
        self.administrative_state = administrative_state
        self.dist_names = dist_names
